482	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
483	        if (!claim.getStatus().isOpen()) {
484	            throw new ResponseStatusException(HttpStatus.CONFLICT,
485	                    "Only an OPEN or PENDING claim is reminded, not a " + claim.getStatus() + " one");
486	        }
487	        LocalDate today = sheets.today(sheetId);
488	        if (today.equals(claim.getReminded())) {
489	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded on " + today);
490	        }
491	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
492	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
493	        claim.setReminded(today);
494	        claims.flush();
495	        record("REMIND", user, person, claim, claim.getNumber());
496	        return claim;
