499	    /** A steward re-dates an OPEN or PENDING claim: its due-by stays as it was fixed, a figure a
500	     *  statement bound it to stays bound, and so does its period (that of its due-by) and its
501	     *  number. Refused (404) when missing, (403) for anyone but a steward, (423) when its due-by
502	     *  is in a closed period, (409) unless OPEN or PENDING, and (422) when the new date is after
503	     *  the person's retirement date. */
504	    @Transactional
505	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
506	        Claim claim = claims.findForUpdate(id, sheetId)
507	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
508	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
509	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
510	        }
511	        refuseIfClosed(sheetId, claim.getDueBy());
512	        if (!claim.getStatus().isOpen()) {
513	            throw new ResponseStatusException(HttpStatus.CONFLICT,
514	                    "Only an OPEN or PENDING claim is re-dated, not a " + claim.getStatus() + " one");
515	        }
516	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
517	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
518	        refuseIfRetired(person, date);
519	        RollupService.Snapshot before = rollup.snapshot(sheetId);
520	        LocalDate old = claim.getDate();
521	        claim.setDate(date);
522	        claims.flush();
523	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), " old=" + old + " new=" + date);
524	        rollup.recordChanges(sheetId, user, before);
525	        return claim;
