528	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
529	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
530	     *  opened or last edited it, (423) when it is due in a closed period, and (422) when its due is above the
531	     *  proof threshold in force on its date while it has no proof. */
532	    @Transactional
533	    public Claim approve(String sheetId, String user, long id) {
534	        Claim claim = pendingForSteward(sheetId, user, id);
535	        if (user.equals(claim.getOpenedBy())) {
536	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
537	                    "The user who opened a claim cannot approve it");
538	        }
539	        if (user.equals(claim.getEditedBy())) {
540	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
541	                    "The user who last edited a claim cannot approve it");
542	        }
543	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
544	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
545	        BigDecimal due = shownDueOf(claim, person);
546	        refuseIfUnproven(claim, person, due);
547	        RollupService.Snapshot before = rollup.snapshot(sheetId);
548	        claim.setStatus(ClaimStatus.SETTLED);
549	        claim.setSettledDue(due);
