552	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
553	        notifyWatchers(user, person, claim.getNumber());
554	        rollup.recordChanges(sheetId, user, before);
555	        return claim;
