745	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
746	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
747	    private Claim pendingForSteward(String sheetId, String user, long id) {
748	        Claim claim = claims.findForUpdate(id, sheetId)
749	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
750	        refuseIfClosed(sheetId, claim.getDueBy());
751	        if (claim.getStatus() != ClaimStatus.PENDING) {
752	            throw new ResponseStatusException(HttpStatus.CONFLICT,
753	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
754	        }
755	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
756	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
757	                    "Only a steward approves or rejects a PENDING claim");
758	        }
759	        return claim;
760	    }
