762	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
763	     *  it shows at this moment. */
764	    private void logStatus(String user, Person person, Claim claim) {
765	        BigDecimal due = shownDueOf(claim, person);
766	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
767	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
