774	    /** Take a statement of a person: record their due-total now, and bind each of their claims
775	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
776	     *  are left unbound. Taken as of a date ({@code asOf}, not null), the sheet as it stood at the end
777	     *  of that date stands in for it now (see {@link #statementAsOf}). */
778	    @Transactional
779	    public Statement statement(String sheetId, String user, long personId, LocalDate asOf) {
780	        if (asOf != null) {
781	            return statementAsOf(sheetId, user, personId, asOf);
782	        }
783	        Person person = people.findForUpdate(personId, sheetId)
784	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
785	        LocalDate today = sheets.today(sheetId);
786	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
787	        RollupService.Snapshot before = rollup.snapshot(sheetId);
788	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
789	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
790	        for (Claim c : theirs) {
791	            if (counts(c, person, today)) {
792	                // the statement binds the figure; the late charge keeps following the sheet's today
793	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
794	            } else {
795	                c.unbind();
796	            }
797	        }
798	        claims.flush();
799	        return stated(sheetId, user, person, theirs, dueTotal, counted.size(), today, null, before);
800	    }
