802	    /** Take a statement of a person as of a date on or before the sheet's today: their claims that
803	     *  counted at the end of it are bound to their figures as they stood then (every change made
804	     *  while the sheet's today was on or before it counts, every later one does not), with that date
805	     *  standing in for the sheet's today in every figure; their other claims are left unbound.
806	     *  Refused (422) when the date is after the sheet's today, or the person was not yet added then. */
807	    private Statement statementAsOf(String sheetId, String user, long personId, LocalDate asOf) {
808	        Person person = people.findForUpdate(personId, sheetId)
809	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
810	        LocalDate today = sheets.today(sheetId);
811	        if (asOf.isAfter(today)) {
812	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
813	                    "A statement is taken as of a date on or before the sheet's today");
814	        }
815	        HistoryService.AsOf then = history.asOf(sheetId, asOf);
816	        Person was = then.people().get(personId);
817	        if (was == null) {
818	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
819	                    "The person was not yet on the sheet on " + asOf);
820	        }
821	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
822	        RollupService.Snapshot before = rollup.snapshot(sheetId);
823	        RollupService.Stated stated = RollupService.statedOn(then.sheet(), was, personId,
824	                List.copyOf(then.claims().values()), then.rates());
825	        Map<Long, BigDecimal> bound = new HashMap<>();
826	        then.claims().forEach((id, c) -> {
827	            if (stated.counted().containsKey(c)) {
828	                bound.put(id, stated.counted().get(c));
829	            }
830	        });
831	        for (Claim c : theirs) {
832	            if (bound.containsKey(c.getId())) {
833	                c.bind(bound.get(c.getId()));
834	            } else {
835	                c.unbind();
836	            }
837	        }
838	        claims.flush();
839	        return stated(sheetId, user, person, theirs, stated.dueTotal(), stated.counted().size(), today, asOf, before);
840	    }
