842	    /** Record a statement just taken (as of {@code asOf}, or null) and audit it. */
843	    private Statement stated(String sheetId, String user, Person person, List<Claim> theirs, BigDecimal dueTotal,
844	            int counted, LocalDate today, LocalDate asOf, RollupService.Snapshot before) {
845	        statements.saveAndFlush(new PersonStatement(sheetId, person.getId(), dueTotal, counted, today, asOf, user));
846	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
847	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted
848	                + (asOf == null ? "" : " asof=" + asOf));
849	        rollup.recordChanges(sheetId, user, before);
850	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(person.getId())), theirs);
851	    }
