853	    /** A steward cancels a person's last statement: it is removed, and every claim it bound is
854	     *  live again (a figure an earlier statement bound is not restored). Refused (404) when the
855	     *  person is missing, (403) for anyone but a steward, and (409) when the person has no
856	     *  statement. */
857	    @Transactional
858	    public Statement cancelStatement(String sheetId, String user, long personId) {
859	        Person person = people.findForUpdate(personId, sheetId)
860	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
861	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
862	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement");
863	        }
864	        List<PersonStatement> taken = statements.findByPersonIdOrderByIdAsc(personId);
865	        if (taken.isEmpty()) {
866	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
867	        }
868	        PersonStatement last = taken.get(taken.size() - 1);
869	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
870	        RollupService.Snapshot before = rollup.snapshot(sheetId);
871	        theirs.forEach(Claim::unbind);
872	        claims.flush();
873	        statements.delete(last);
874	        statements.flush();
875	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
876	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
877	        rollup.recordChanges(sheetId, user, before);
878	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
879	    }
