881	    /** The terms a claim of the person dated {@code on} is fixed with as it is created: the
882	     *  person's own terms, else those of their grade then in force on it, else the sheet's. */
883	    private int termsOf(String sheetId, Person person, LocalDate on) {
884	        return person.getTerms() != null ? person.getTerms()
885	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
