895	    /** A holiday just added re-fixes the due-by of every claim on the sheet that is neither SETTLED
896	     *  nor VOID and is due on or after it: from its date, with the terms it was fixed with, over the
897	     *  holidays on the sheet now. The figures that moves are recorded. */
898	    @EventListener
899	    @Transactional
900	    public void redate(HolidayAdded added) {
901	        String sheetId = added.sheetId();
902	        RollupService.Snapshot before = rollup.snapshot(sheetId);
903	        Set<LocalDate> holidays = new HashSet<>(settings.holidays(sheetId));
904	        for (Claim c : claims.findBySheetIdForUpdate(sheetId)) {
905	            if (c.getStatus() == ClaimStatus.SETTLED || c.getStatus() == ClaimStatus.VOID
906	                    || c.getDueBy().isBefore(added.day())) {
907	                continue;
908	            }
909	            c.setDueBy(BusinessDays.after(c.getDate(), c.getTerms(), holidays));
910	        }
911	        claims.flush();
912	        rollup.recordChanges(sheetId, added.user(), before);
913	    }
