915	    /** The number a claim due by {@code date} takes as it is opened: under period numbering (set,
916	     *  and the sheet's today on or after it) the next within the period containing the due-by
917	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
918	    private String nextNumber(String sheetId, LocalDate date) {
919	        if (!sheets.periodNumberingOn(sheetId)) {
920	            return String.valueOf(sheets.nextClaimNumber(sheetId));
921	        }
922	        // held until the transaction ends, so two claims opened at once are numbered one after the other
923	        sheets.lock(sheetId);
924	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
925	        List<String> given = new ArrayList<>(claims.findNumbers(sheetId));
926	        given.addAll(retired.findNumbers(sheetId));
927	        int last = given.stream()
928	                .filter(n -> n.startsWith(prefix))
929	                .map(n -> n.substring(prefix.length()))
930	                .filter(n -> n.matches("\\d{1,9}"))
931	                .mapToInt(Integer::parseInt)
932	                .max().orElse(0);
933	        return prefix + (last + 1);
934	    }
