951	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
952	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
953	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
954	        if (amount.signum() >= 0) {
955	            return null;
956	        }
957	        if (corrects == null
958	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
959	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
960	                    "A negative amount must correct a settled claim of the same person");
