966	     *  another claim on the sheet than the one of the id (null: a new claim) already carries it,
967	     *  comparing without regard to case. */
968	    private String refOf(String sheetId, Long id, String ref) {
969	        if (ref == null || ref.isBlank()) {
970	            return null;
971	        }
972	        String trimmed = ref.trim();
973	        if (claims.existsRef(sheetId, trimmed, id)) {
974	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The reference " + trimmed + " is already used on the sheet");
975	        }
976	        return trimmed;
