979	    /** A claim's tags as the form gives them, comma separated: each trimmed and lower-cased, blank
980	     *  ones and repeats dropped, sorted and joined by commas; none when no tag is left. */
981	    static String tagsOf(String tags) {
982	        if (tags == null) {
983	            return null;
984	        }
985	        Set<String> each = new TreeSet<>();
986	        for (String tag : tags.split(",")) {
987	            String t = tag.trim().toLowerCase(Locale.ROOT);
988	            if (!t.isEmpty()) {
989	                each.add(t);
990	            }
991	        }
992	        return each.isEmpty() ? null : String.join(",", each);
993	    }
