995	    /** Keep each of the claim's tags among those ever used on its sheet. */
996	    private void keepTags(Claim claim) {
997	        if (claim.getTags() == null) {
998	            return;
999	        }
1000	        for (String tag : claim.getTags().split(",")) {
1001	            if (!tagsUsed.existsBySheetIdAndTag(claim.getSheetId(), tag)) {
1002	                tagsUsed.save(new SheetTag(claim.getSheetId(), tag));
1003	            }
1004	        }
