1007	    /** Refuse (422) a claim dated after its person's retirement date. */
1008	    private static void refuseIfRetired(Person person, LocalDate date) {
1009	        if (person.retiredBefore(date)) {
1010	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
1011	                    "The date is after the person's retirement date");
1012	        }
1013	    }
