1015	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
1016	     *  do, but not an open one dated within a hold of its person, nor one of a person whose
1017	     *  retirement date the sheet's today has reached, unless bound by a statement, nor one deferred
1018	     *  on the sheet's today. */
1019	    private static boolean counts(Claim c, Person person, LocalDate today) {
1020	        return c.getStatus() == ClaimStatus.SETTLED
1021	                || (c.getStatus().isOpen() && !c.isDeferredOn(today)
1022	                        && (c.isBound() || !(person.heldOn(c.getDate()) || person.retiredOn(today))));
1023	    }
1024	
1025	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
1026	     *  charge on top, raised to the floor in force on its date. */
1027	    private BigDecimal shownDueOf(Claim claim, Person person) {
1028	        if (claim.getSettledDue() != null) {
1029	            return claim.getSettledDue();
1030	        }
1031	        return flooredOf(claim,
1032	                LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, person, figureOf(claim, person), roundingOf(claim)));
1033	    }
1034	
1035	    /** A due (null: n/a, which stays n/a) raised to the sheet's floor in force on the claim's date; a
1036	     *  correction's never is. */
1037	    private BigDecimal flooredOf(Claim claim, BigDecimal due) {
1038	        if (due == null || claim.isCorrection()) {
1039	            return due;
1040	        }
1041	        return due.max(sheets.floorOn(claim.getSheetId(), claim.getDate()));
1042	    }
1043	
1044	    /** A claim's figure before any late charge or floor: the one a statement bound it to (null: n/a),
1045	     *  else (unbound, or PENDING) its rate figure. */
1046	    private BigDecimal figureOf(Claim claim, Person person) {
1047	        return claim.isBound() ? claim.getStatedDue() : rateFigureOf(claim, person);
1048	    }
1049	
1050	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
1051	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
1052	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
1053	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
1054	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
1055	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
1056	            return null;
1057	        }
1058	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
1059	    }
1060	
1061	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
1062	     *  100, rounded as its rounding policy has it; null with no rate in force then. */
1063	    private BigDecimal rateFigureOf(Claim claim, Person person) {
1064	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
1065	                .map(Rate::getPct)
1066	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
1067	                .orElse(null);
1068	    }
