1070	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
1071	     *  correction the date of the claim it corrects. */
1072	    private RoundingMode roundingOf(Claim claim) {
1073	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
1074	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
1075	                        .map(Claim::getDate).orElse(claim.getDate());
1076	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
1077	    }
